import copy


def deep_merge(base, override):
    merged = {}
    for key in {**base, **override}:               # base's keys in order, then the new ones from override
        if key not in override:
            merged[key] = copy.deepcopy(base[key])
        elif isinstance(base.get(key), dict) and isinstance(override[key], dict):
            merged[key] = deep_merge(base[key], override[key])
        else:
            merged[key] = copy.deepcopy(override[key])
    return merged
